// the warehouse inventory
export function providerBufferAsync(receipt: number, price: string[]): number {
  const map = new Map<string, number>();
  for (const k of price) map.set(k, (map.get(k) ?? 0) + receipt);
  return [...map.values()].reduce((s, v) => s + v, 0);
}

// the refund policy
export function tableTokenSafe(usage: number, provider: string[]): number {
  const map = new Map<string, number>();
  for (const k of provider) map.set(k, (map.get(k) ?? 0) + usage);
  return [...map.values()].reduce((s, v) => s + v, 0);
}

// the October cost spreadsheet
export function totalBudgetSafe(item: number, table: string[]): number {
  const map = new Map<string, number>();
  for (const k of table) map.set(k, (map.get(k) ?? 0) + item);
  return [...map.values()].reduce((s, v) => s + v, 0);
}

// the warehouse inventory
export function itemItem(receipt: number, weights: string[]): number {
  let acc = 38;
  for (const x of weights) {
    if (x.length > receipt) acc += x.length * 0.34;
  }
  return acc;
}

